{
  "status": "SUPPORTED",
  "task_summary": "Find fastening parts in storage, attach them to a workpiece on the bench, and put the tool back on the bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_part",
        "entity_kind": "OBJECT",
        "function": "Physical item needed to secure the workpiece.",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "nut", "clip"],
        "required_properties": ["compatible_with_workpiece", "secure_connection"]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "Item at the marked location receiving the fastening.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["panel", "device", "assembly"],
        "required_properties": ["has_connection_point", "fixed_in_place"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Device used to apply the fastening part.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["screwdriver", "wrench", "drill", "grip"],
        "required_properties": ["mechanical_action", "reusable"]
      },
      {
        "id": "storage_zone",
        "entity_kind": "REGION",
        "function": "Enclosed area where parts or tools may be hidden.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "drawer_set"],
        "required_properties": ["enclosed", "openable"]
      },
      {
        "id": "workbench_surface",
        "entity_kind": "REGION",
        "function": "Surface where the tool is left after use.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table_top", "desk"],
        "required_properties": ["flat", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "rel_fit",
        "relation": "COMPATIBLE_WITH",
        "participant_roles": ["fastening_part", "workpiece"],
        "required": true
      },
      {
        "id": "rel_act",
        "relation": "OPERATES_ON",
        "participant_roles": ["fastening_tool", "fastening_part", "workpiece"],
        "required": true
      },
      {
        "id": "rel_end",
        "relation": "ENDS_UP_ON",
        "participant_roles": ["fastening_tool", "workbench_surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_search",
        "operation": "SEARCH_STORAGE",
        "participant_roles": ["fastening_part", "storage_zone"],
        "operation_count": 1
      },
      {
        "id": "op_fasten",
        "operation": "FASTEN_PART",
        "participant_roles": ["fastening_tool", "fastening_part", "workpiece"],
        "operation_count": 1
      },
      {
        "id": "op_place",
        "operation": "PLACE_TOOL",
        "participant_roles": ["fastening_tool", "workbench_surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_part": [
        {
          "label": "yellow_block",
          "visual_description": "Yellow rectangular object on the tray."
        },
        {
          "label": "blue_block",
          "visual_description": "Blue rectangular object on the tray."
        }
      ],
      "workpiece": [
        {
          "label": "tray_assembly",
          "visual_description": "Black tray containing yellow and blue parts."
        }
      ],
      "fastening_tool": [],
      "storage_zone": [
        {
          "label": "blue_cabinet",
          "visual_description": "Tall blue cabinet standing against the wall."
        },
        {
          "label": "under_table_drawers",
          "visual_description": "Two blue drawers located beneath the wooden table."
        }
      ],
      "workbench_surface": [
        {
          "label": "wooden_tabletop",
          "visual_description": "Wooden surface of the desk."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue_cabinet",
        "visual_description": "Closed blue cabinet.",
        "reason": "Enclosed storage structure."
      },
      {
        "id": "under_table_drawers",
        "label": "under_table_drawers",
        "visual_description": "Closed drawers under table.",
        "reason": "Enclosed storage structure."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "under_table_drawers"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
